function CAMPOS(itens, titulo) { return { tipo: 'campos', titulo: titulo, itens: itens }; }
function BOTOES(itens) { return { tipo: 'botoes', itens: itens }; }
function blocoLink(op) {
  var i = op.link ? op : infoOp(op);
  if (i.link.tg) return P('<b>Programa no Transferegov:</b> <a href="' + esc(i.link.url) + '">' + esc(i.link.rotulo) + '</a>. No portal, busque pelo nome do programa: <i>' + esc(i.titulo) + '</i>.');
