var ROTULO_PARCEIRA = 'Em parceria com uma empresa (cliente ou parceiro do Modal)';

var REC = { seguir: 'Seguir', avaliar: 'Avaliar', nao_seguir: 'Não seguir' };
var ESF = { baixo: 'Baixo', medio: 'Médio', alto: 'Alto' };
var SIT = { nova: 'Sem resposta', avisada: 'Sem resposta', concorrer: 'Vamos concorrer', talvez: 'Talvez', nao_serve: 'Não serve', enviada: 'Proposta enviada', ganhou: 'Ganhou', perdeu: 'Perdeu', desistiu: 'Desistiu' };
var DECIDIVEL = ['nova', 'avisada', 'talvez', 'concorrer'];
var CERTS = {
  federal: { nome: 'Certidão de débitos federais (Receita Federal e PGFN)', url: 'https://servicos.receitafederal.gov.br/servico/certidoes/', nota: 'informe o CNPJ; sai na hora quando não há pendência.' },
  fgts: { nome: 'Certificado de Regularidade do FGTS (CRF, Caixa)', url: 'https://consulta-crf.caixa.gov.br/consultacrf/pages/consultaEmpregador.jsf', nota: 'vale 30 dias e só pode ser renovado a partir de 5 dias antes de vencer: por isso é emitido perto da entrega.' },
  trabalhista: { nome: 'Certidão Negativa de Débitos Trabalhistas (CNDT, TST)', url: 'https://cndt-certidao.tst.jus.br/inicio.faces', nota: 'informe o CNPJ.' },
  df: { nome: 'Certidão negativa de débitos do Distrito Federal (Receita do DF, Secretaria de Economia)', url: 'https://ww1.receita.fazenda.df.gov.br/cidadao/certidoes/Certidao', nota: 'confira a validade impressa na certidão.' }
};
var ORDEM_CERT = ['federal', 'fgts', 'trabalhista', 'df'];

function txt(v) { return String(v == null ? '' : v).trim(); }
function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;'); }
// Só endereço público (mesma trava da triagem): o link do edital vem do texto lido pela IA e não pode levar o robô a serviço interno.
function enderecoPublico(u) {
  var m = String(u || '').trim().match(/^https?:\/\/([^\/?#:@]+)(:(?:80|443))?([\/?#]|$)/i);
  if (!m) return false;
  var h = m[1].toLowerCase().replace(/\.$/, '');
  // Nome de domínio comum: rótulos só com letras, números e hífen, terminando em domínio de letras
  // (recusa IP em qualquer grafia, como 0x7f.0.0.1 ou 0177.1, barra invertida e %).
  if (!/^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}$/.test(h)) return false;
  if (/(^|\.)(localhost|local|internal|lan|home|arpa)$/.test(h)) return false;
  if (/(^|\.)modal\.org\.br$/.test(h)) return false;
  return true;
}
function seguro(u) { var v = txt(u); return /^https?:\/\/[^\s"'<>]+$/i.test(v) && enderecoPublico(v) ? v : ''; }
function normTxt(s) { return String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(); }
function tam(s) { return String(s || '').replace(/\s+/g, '').length; }
function itensDe(v) { return (Array.isArray(v) ? v : String(v || '').split('\n')).map(function (s) { return String(s).replace(/^[-•*\s]+/, '').trim(); }).filter(Boolean); }

// ---------- datas (AAAA-MM-DD, fuso de São Paulo, sem horário de verão desde 2019) ----------
function dia(v) {
  if (v == null || v === '') return '';
  if (Object.prototype.toString.call(v) === '[object Date]') v = v.toISOString();
  var s = String(v).trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  var t = Date.parse(s);
  if (isNaN(t)) { var m = s.match(/^(\d{4}-\d{2}-\d{2})/); return m ? m[1] : ''; }
  return new Date(t - 3 * 3600 * 1000).toISOString().slice(0, 10);
}
function utc(iso) { return Date.parse(iso + 'T00:00:00Z'); }
function diasEntre(a, b) { return Math.round((utc(b) - utc(a)) / 86400000); }
function somaDias(iso, n) { return new Date(utc(iso) + n * 86400000).toISOString().slice(0, 10); }
function br(iso) { var m = String(iso || '').match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? m[3] + '/' + m[2] + '/' + m[1] : ''; }
function faltam(n) { return n <= 0 ? 'é hoje' : n === 1 ? 'falta 1 dia' : 'faltam ' + n + ' dias'; }
function porPrazo(a, b) { return (a.prazo || '9999-12-31').localeCompare(b.prazo || '9999-12-31'); }

// ---------- execução: produção x teste ----------
// Produção = fluxo gerado com --producao (modoTeste false) E execução agendada. Manual ou modoTeste: e-mail só para o endereço de teste,
// com [TESTE] no assunto, e só oportunidades "[TESTE]" têm a situação alterada. Em produção, "[TESTE]" é ignorado.
function contexto(cfg, modoN8n) {
  var agendada = modoN8n === 'production' || modoN8n === 'trigger';
  var producao = cfg.modoTeste === false && agendada;
  return { producao: producao, para: producao ? cfg.lista : cfg.emailTeste, prefixo: producao ? '' : '[TESTE] ' };
}
function ehTeste(op) { return /^\s*\[TESTE\]/i.test(txt(op.titulo)) || /^\s*\[TESTE\]/i.test(txt(op.titulo_oficial)); }

// ---------- oportunidade ----------
function ehApiTransferegov(u) { return /^https?:\/\/api-publica\.transferegov\./i.test(txt(u)); }
// Link para leitura de gente. Programa do Transferegov não tem página pública (a API devolve JSON): vai o caminho de envio e a instrução de busca.
function linkOp(op) {
  var cands = [seguro(op.link_edital_oficial), seguro(op.url)].filter(Boolean);
  var normal = cands.filter(function (u) { return !ehApiTransferegov(u); })[0] || '';
  var prog = txt(op.tipo_oportunidade) === 'programa_aberto';
  if (normal) return { tg: false, url: normal, rotulo: prog ? 'Programa' : 'Edital oficial' };
  if (cands.some(ehApiTransferegov) || prog) return { tg: true, url: TG_ENVIO, rotulo: TG_ROTULO };
  return { tg: false, url: '', rotulo: 'Edital oficial' };
}
function infoOp(op) {
  return {
    chave: txt(op.chave), titulo: txt(op.titulo_oficial) || txt(op.titulo), ofertante: txt(op.ofertante), prazo: dia(op.prazo), valor: txt(op.valor),
    resumo: txt(op.resumo), publico: txt(op.publico_elegivel), papel: txt(op.papel_modal), fonte: txt(op.fonte), prog: txt(op.tipo_oportunidade) === 'programa_aberto',
    link: linkOp(op), teste: ehTeste(op)
  };
}
function papelRotulo(papel) {
  if (papel === 'parceira') return ROTULO_PARCEIRA;
  if (papel === 'proponente') return 'O Modal pode ser o proponente (ICT)';
  return 'Papel do Modal a confirmar no edital';
}

// ---------- blocos de e-mail (formato do subfluxo "Modal – Enviar e-mail") ----------
function P(html) { return { tipo: 'paragrafo', html: html }; }
function PT(texto) { return { tipo: 'paragrafo', texto: texto }; }
function H(texto) { return { tipo: 'subtitulo', texto: texto }; }
function UL(itens) { return { tipo: 'lista', itens: itens }; }
function AV(texto, tom) { return { tipo: 'aviso', texto: texto, tom: tom || 'atencao' }; }
function CAMPOS(itens, titulo) { return { tipo: 'campos', titulo: titulo, itens: itens }; }
function BOTOES(itens) { return { tipo: 'botoes', itens: itens }; }
function blocoLink(op) {
  var i = op.link ? op : infoOp(op);
  if (i.link.tg) return P('<b>Programa no Transferegov:</b> <a href="' + esc(i.link.url) + '">' + esc(i.link.rotulo) + '</a>. No portal, busque pelo nome do programa: <i>' + esc(i.titulo) + '</i>.');
  if (i.link.url) return P('<b>' + esc(i.prog ? 'Programa oficial' : 'Edital oficial') + ':</b> <a href="' + esc(i.link.url) + '">' + esc(i.link.url) + '</a>');
  return PT('Link do edital não identificado; procure no site do ofertante.');
}
function urlDecisao(token, d) { return BASE_DECISAO + '?t=' + encodeURIComponent(token) + '&d=' + d; }
function botoesDecisao(token) { return BOTOES([{ rotulo: 'Vamos concorrer', url: urlDecisao(token, 'concorrer') }, { rotulo: 'Talvez', url: urlDecisao(token, 'talvez') }, { rotulo: 'Não serve', url: urlDecisao(token, 'nao_serve') }]); }
function novoEmail(cfg, ctx, e) {
  return {
    para: ctx.para, assunto: ctx.prefixo + e.assunto, nomeRemetente: cfg.remetente, responderPara: cfg.lista,
    etiqueta: e.etiqueta, titulo: e.titulo, previa: e.previa, blocos: e.blocos, rodape: RODAPE, _marca: e.marca || null
  };
}

// ---------- resposta do subfluxo de e-mail ----------
// O subfluxo devolve a resposta do Gmail (tem "id") ou falha. Só conta como enviado o que voltou com id.
function enviado(resp) { return !!(resp && typeof resp === 'object' && !resp.error && typeof resp.id === 'string' && resp.id); }

// Captação – Avaliação: funções puras (testadas com carregar.js). Embutido depois de comum.js.

var LIMITE_TEXTO = 120000;
var PASSO_CERT = 'Emitir as certidões exigidas (federal, FGTS, trabalhista, DF) perto da entrega; o pacote de quem decide concorrer traz os links.';
var PASSO_PARCEIRA = 'Ver qual cliente ou parceiro do Modal poderia propor esta chamada e convidá-lo a entrar com o Modal (a empresa propõe; o Modal entra como ICT parceira).';
var CERT_RX = /certid[aã]o|certid[oõ]es|\bcnd\b|cndt|regularidade (do|com o|perante o) fgts|\bfgts\b|d[eé]bitos trabalhistas|regularidade fiscal/i;
var PERFIL_MODAL = 'Instituto Modal: ICT (Instituição Científica, Tecnológica e de Inovação) privada sem fins lucrativos, associação sediada em Brasília-DF desde 2017. NÃO é OSCIP.';

function ehCertidao(x) { return /^certid/i.test(txt(x['Seção'])) || /certid[aã]o negativa|regularidade do fgts|d[eé]bitos trabalhistas/i.test(txt(x['Item'])); }

function lerHtml(html) {
  var h = String(html || '').replace(/<(script|style|noscript|svg)\b[\s\S]*?<\/\1>/gi, ' ').replace(/<(nav|header|footer)\b[\s\S]*?<\/\1>/gi, ' ');
  var t = h.replace(/<(br|p|div|li|tr|h[1-6]|section|article|dt|dd)\b[^>]*>/gi, '\n').replace(/<[^>]+>/g, ' ');
  t = t.replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'").replace(/&lt;/gi, '<').replace(/&gt;/gi, '>');
  return t.replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
}

// Fila da rodada. o: { aprovadas, avaliacoes, dossie, carteira, organizacao (linhas da aba), hoje, producao, limite }
// Oportunidade aprovada sem linha de avaliação, do prazo mais próximo ao mais distante; vencida não é avaliada; "[TESTE]" só fora da produção.
function montarFila(o) {
  var existentes = {};
  (o.avaliacoes || []).forEach(function (a) { if (a && a.chave_oportunidade) existentes[a.chave_oportunidade] = true; });
  var org = (o.organizacao || []).filter(function (r) { return r && txt(r['Organização']); })[0] || {};
  var dossie = (o.dossie || []).filter(function (d) { return d && txt(d['Item']); });
  var carteira = (o.carteira || []).filter(function (c) { return c && txt(c['Projeto']); });
  var cand = [];
  (o.aprovadas || []).forEach(function (op) {
    if (!op || !op.chave || op.situacao_triagem !== 'aprovada' || op.duplicata_de) return;
    if (existentes[op.chave]) return;
    if (o.producao && ehTeste(op)) return;
    var prazo = dia(op.prazo);
    if (prazo && prazo < o.hoje) return;
    cand.push({ op: op, prazo: prazo });
  });
  cand.sort(porPrazo);
  var semCert = dossie.filter(function (x) { return !ehCertidao(x); });
  var lacunas = semCert.filter(function (x) { return /^(falta|verificar)/i.test(txt(x['Situação'])); }).length;
  var motivosBase = [];
  if (!dossie.length) motivosBase.push('o dossiê da organização está vazio');
  else if (lacunas >= Math.max(5, Math.ceil(semCert.length / 3))) motivosBase.push(lacunas + ' de ' + semCert.length + ' itens do dossiê (fora as certidões) constam como "Falta" ou "Verificar"');
  if (!carteira.length) motivosBase.push('a carteira de projetos está vazia');
  var dossieTxt = semCert.map(function (x) {
    return '- [' + txt(x['Seção']) + '] ' + txt(x['Item']) + ': ' + (txt(x['Situação']) || 'sem situação') + (txt(x['Validade']) ? '; validade ' + txt(x['Validade']) : '') + (txt(x['Observação']) ? ' — ' + txt(x['Observação']).slice(0, 350) : '');
  }).join('\n') + (dossie.length > semCert.length ? '\n- [Certidões] Certidões negativas (federal, FGTS, trabalhista, DF): emitidas só quando a organização decide concorrer, perto da entrega; NÃO contam como falta nesta avaliação.' : '');
  var carteiraTxt = carteira.map(function (c) {
    return '- ' + txt(c['Projeto']) + ' (' + (txt(c['Situação']) || 'sem situação') + '): público: ' + txt(c['Público']) + '; problema: ' + txt(c['Problema que resolve']) + '; atividades: ' + txt(c['Principais atividades']) + '; orçamento estimado R$ ' + txt(c['Orçamento estimado (R$)']) + '; duração ' + txt(c['Duração (meses)']) + ' meses; impacto: ' + txt(c['Impacto esperado e indicadores']) + '; temas: ' + txt(c['Temas']);
  }).join('\n');
  return cand.slice(0, o.limite || 10).map(function (c) {
    var op = c.op, url = seguro(op.link_edital_oficial) || seguro(op.url);
    var semPagina = !url || !!txt(op.texto_fonte) && (ehApiTransferegov(url) || ehApiTransferegov(op.url) || /^https?:\/\/(ec\.europa\.eu|api\.tech\.ec\.europa\.eu)\//i.test(url));
    return {
      chave: op.chave, url: url, leitura: semPagina ? 'sem_pagina' : 'buscar', texto_fonte: txt(op.texto_fonte), tipo_oportunidade: txt(op.tipo_oportunidade) || 'edital',
      papel_modal: txt(op.papel_modal), prazo: c.prazo,
      op: { titulo: txt(op.titulo_oficial) || txt(op.titulo), ofertante: txt(op.ofertante), numero_edital: txt(op.numero_edital), tipo_instrumento: txt(op.tipo_instrumento), publico_elegivel: txt(op.publico_elegivel), regiao: txt(op.regiao), prazo: c.prazo, valor: txt(op.valor), temas: txt(op.temas), resumo: txt(op.resumo), link: url },
      org_perfil: { areas: txt(org['Áreas de atuação']), publico: txt(org['Público atendido']), regiao: txt(org['Região']), observacoes: txt(org['Observação']) },
      dossie_txt: dossieTxt, carteira_txt: carteiraTxt, projetos: carteira.map(function (x) { return txt(x['Projeto']); }), motivos_parcial: motivosBase.slice()
    };
  });
}

// Texto do edital: PDF (resp.text), página (resp.data), erro ou nada; o texto guardado na coleta entra junto. Cortado em 120 mil caracteres.
function prepararTexto(f, resp) {
  resp = resp || {};
  var base = txt(f.texto_fonte), pag = '', fonte = '';
  if (f.leitura !== 'sem_pagina' && !resp.error) {
    if (typeof resp.text === 'string') { pag = resp.text; fonte = 'PDF'; }
    else if (typeof resp.data === 'string') { pag = lerHtml(resp.data); fonte = 'página'; }
  }
  pag = String(pag || '').replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
  var texto = pag && base && tam(pag) < 400 ? base + '\n\n--- PÁGINA ---\n' + pag : (pag || base);
  if (!pag || tam(pag) < 400) fonte = base ? 'texto da coleta' : fonte;
  var cortado = texto.length > LIMITE_TEXTO;
  return { texto: texto.slice(0, LIMITE_TEXTO), fonte: fonte || 'página', cortado: cortado, leitura_ok: tam(texto) >= 400 };
}

function montarPedido(f, p, hoje) {
  var motivos = f.motivos_parcial.slice();
  if (!p.leitura_ok) motivos.unshift('o edital não pôde ser lido por inteiro; avaliação feita só com os dados da triagem');
  var op = f.op, o = f.org_perfil;
  var prog = f.tipo_oportunidade === 'programa_aberto';
  var notaPrograma = prog ? 'TIPO DE OPORTUNIDADE: programa federal ABERTO A PROPOSTAS VOLUNTÁRIAS no Transferegov, sem chamamento e sem seleção competitiva. A organização cadastra proposta e plano de trabalho no Transferegov até a data limite do programa; o órgão analisa o enquadramento e a disponibilidade orçamentária e pode ou não celebrar a parceria: não há garantia de recurso nem classificação entre concorrentes. Avalie assim: a aderência mede o encaixe do objeto do programa com o Modal e a capacidade de propor e executar; recomendação "seguir" significa que vale cadastrar a proposta, não que o recurso é provável; a justificativa deve dizer, em uma frase, que é programa aberto a propostas, sem seleção e sem garantia de recurso; os próximos passos devem incluir cadastrar a proposta no Transferegov até a data limite e buscar apoio para o repasse junto à área técnica do órgão concedente. Não fale em classificação nem nota de corte.\n\n' : '';
  var notaParceira = f.papel_modal === 'parceira' ? 'PAPEL DO MODAL NESTA OPORTUNIDADE: quem propõe é uma EMPRESA; o Modal entra como ICT parceira (executora) da empresa proponente, não como proponente. Avalie o encaixe do Modal como ICT parceira (capacidade técnica, áreas, clientes e parceiros do Modal no setor) e inclua nos próximos passos ver qual cliente ou parceiro do Modal poderia propor e convidá-lo a entrar com o Modal.\n\n' : '';
  var prompt = 'Hoje é ' + hoje + '. Avalie se o Modal deve ir atrás desta oportunidade.\n\n' +
    'PERFIL FIXO: ' + PERFIL_MODAL + '\n\n' +
    'OPORTUNIDADE (dados da triagem)\n- Título: ' + op.titulo + '\n- Tipo de oportunidade: ' + (prog ? 'programa aberto a propostas voluntárias, sem seleção' : 'edital ou chamada') + '\n- Ofertante: ' + op.ofertante + '\n- Número: ' + (op.numero_edital || 'não informado') + '\n- Tipo: ' + op.tipo_instrumento + '\n- Quem pode concorrer: ' + op.publico_elegivel + '\n- Região: ' + op.regiao + '\n- Prazo: ' + (op.prazo || 'não informado') + '\n- Valor: ' + (op.valor || 'não informado') + '\n- Temas: ' + op.temas + '\n- Resumo: ' + op.resumo + '\n- Link oficial: ' + (ehApiTransferegov(op.link) ? '(programa do Transferegov; sem página pública)' : op.link) + '\n\n' +
    'ORGANIZAÇÃO (planilha)\n- Áreas de atuação: ' + o.areas + '\n- Público atendido: ' + o.publico + '\n- Região: ' + o.regiao + (o.observacoes ? '\n- Observação: ' + o.observacoes : '') + '\n\n' +
    'DOSSIÊ DO MODAL (item: situação; "Tem" = documento em ordem; "Falta" = o Modal ainda não tem; "Não tem" = não possui (se o edital exigir, é impeditivo ou precisa ser providenciado); "Não se aplica" = só é providenciado quando um projeto exige, não conta como falta; "Verificar" = ainda não conferido)\n' + (f.dossie_txt || '(vazio)') + '\n\n' +
    'CARTEIRA DE PROJETOS DO MODAL\n' + (f.carteira_txt || '(vazia: ainda não há projetos cadastrados)') + '\n\n' +
    notaParceira + notaPrograma +
    (motivos.length ? 'Esta avaliação será marcada como parcial (' + motivos.join('; ') + '); o aviso de parcialidade é acrescentado automaticamente, então não o repita na justificativa.\n\n' : '') +
    'CERTIDÕES: certidões negativas (federal, FGTS, trabalhista, DF) são emitidas só quando o Modal decide concorrer, perto da entrega. Não use a falta ou o vencimento delas para reduzir a aderência ou a recomendação, não as cite na justificativa e não as liste em requisitos_atendidos, requisitos_faltantes nem em proximos_passos (o passo de emitir certidões é acrescentado automaticamente).\n\n' +
    'Instruções:\n' +
    '- aderencia: 0 a 100, o quanto o objeto e o público elegível combinam com o Modal e com a capacidade real dele de cumprir as exigências.\n' +
    '- recomendacao: seguir (vale ir atrás), avaliar (pode valer, depende de algo a confirmar) ou nao_seguir.\n' +
    '- justificativa: no máximo 3 frases curtas e concretas.\n' +
    '- projeto_sugerido: o nome exato de um projeto da carteira que se encaixa; vazio se nenhum se encaixa ou se a carteira está vazia.\n' +
    '- esforco: baixo, medio ou alto, considerando documentos a reunir, proposta a escrever e o tempo até o prazo.\n' +
    '- requisitos_atendidos e requisitos_faltantes: cruze as exigências com o dossiê. Um item curto por elemento; não liste o que o edital não exige.\n' +
    '- proximos_passos: 2 a 5 ações práticas, em ordem, com data quando fizer sentido.\n' +
    '- Não invente exigências, valores nem dados que não estejam no edital ou no dossiê.\n\n' +
    'TEXTO DO EDITAL (' + (p.leitura_ok ? p.fonte + (p.cortado ? ', cortado nos primeiros ' + LIMITE_TEXTO + ' caracteres' : '') : 'não lido') + ')\n' + (p.leitura_ok ? p.texto : '(não foi possível ler o edital completo; avalie só com os dados da triagem acima)');
  return { prompt: prompt, leitura_ok: p.leitura_ok, fonte: p.fonte, motivos_parcial: motivos };
}

var ESQUEMA_AVALIACAO = {
  type: 'object',
  properties: {
    aderencia: { type: 'integer', description: '0 a 100' },
    recomendacao: { type: 'string', enum: ['seguir', 'avaliar', 'nao_seguir'] },
    justificativa: { type: 'string' },
    projeto_sugerido: { type: 'string', description: 'nome exato de um projeto da carteira ou vazio' },
    esforco: { type: 'string', enum: ['baixo', 'medio', 'alto'] },
    requisitos_atendidos: { type: 'array', items: { type: 'string' } },
    requisitos_faltantes: { type: 'array', items: { type: 'string' } },
    proximos_passos: { type: 'array', items: { type: 'string' } }
  },
  required: ['aderencia', 'recomendacao', 'justificativa', 'projeto_sugerido', 'esforco', 'requisitos_atendidos', 'requisitos_faltantes', 'proximos_passos']
};
var SISTEMA_AVALIACAO = 'Você é especialista em captação de recursos para instituições científicas e de inovação do Distrito Federal. Avalia editais com realismo: confere as exigências contra os documentos e projetos que a instituição tem, não superestima a aderência, aponta o que falta e escreve em português claro e direto, para quem vai decidir se vai atrás.';

// Valida a saída da IA e monta a linha da avaliação. Saída inválida ou token malformado: gravar=false (nada é gravado; volta na rodada seguinte).
function linhaAvaliacao(f, pedido, ia, token, agoraIso) {
  if (!ia || typeof ia !== 'object' || Array.isArray(ia)) return { gravar: false, motivo: 'saída da IA ausente ou inválida' };
  if (!/^[a-f0-9]{48}$/.test(String(token || ''))) return { gravar: false, motivo: 'token gerado em formato inesperado' };
  var ad = Number(ia.aderencia);
  if (!isFinite(ad)) return { gravar: false, motivo: 'aderência inválida' };
  ad = Math.max(0, Math.min(100, Math.round(ad)));
  if (['seguir', 'avaliar', 'nao_seguir'].indexOf(ia.recomendacao) < 0) return { gravar: false, motivo: 'recomendação inválida' };
  var justificativa = txt(ia.justificativa);
  if (!justificativa) return { gravar: false, motivo: 'justificativa vazia' };
  var esf = ['baixo', 'medio', 'alto'].indexOf(ia.esforco) >= 0 ? ia.esforco : 'medio';
  // projeto sugerido só vale se existir na carteira (nome igual, sem caixa)
  var proj = txt(ia.projeto_sugerido).toLowerCase();
  var projetos = f.projetos || [];
  var projOk = !proj ? '' : (projetos.filter(function (x) { return x.toLowerCase() === proj; })[0] || projetos.filter(function (x) { return x.toLowerCase().indexOf(proj) >= 0 || proj.indexOf(x.toLowerCase()) >= 0; })[0] || '');
  // certidões ficam fora dos requisitos (não reduzem a aderência) e viram um passo fixo
  var atendidos = itensDe(ia.requisitos_atendidos).filter(function (s) { return !CERT_RX.test(s); });
  var faltantes = itensDe(ia.requisitos_faltantes).filter(function (s) { return !CERT_RX.test(s); });
  var passos = itensDe(ia.proximos_passos).filter(function (s) { return !CERT_RX.test(s); });
